package com.rshub;

import net.runelite.api.WorldType;
import org.junit.Test;

import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Verifies special game mode WorldType constants exist for GameModeUtil.
 */
public class GameModeUtilTest
{
	@Test
	public void testSpecialGameModeWorldTypesExist()
	{
		assertNotNull(WorldType.SEASONAL);
		assertNotNull(WorldType.DEADMAN);
		assertNotNull(WorldType.FRESH_START_WORLD);
		assertNotNull(WorldType.TOURNAMENT_WORLD);
		assertNotNull(WorldType.BETA_WORLD);
		assertNotNull(WorldType.NOSAVE_MODE);
		assertNotNull(WorldType.QUEST_SPEEDRUNNING);
	}

	@Test
	public void testWorldTypeEnumContainsSpecialModes()
	{
		WorldType[] types = WorldType.values();
		assertTrue(types.length >= 7);

		WorldType[] specialModes = {
			WorldType.SEASONAL,
			WorldType.DEADMAN,
			WorldType.FRESH_START_WORLD,
			WorldType.TOURNAMENT_WORLD,
			WorldType.BETA_WORLD,
			WorldType.NOSAVE_MODE,
			WorldType.QUEST_SPEEDRUNNING
		};

		for (WorldType specialMode : specialModes)
		{
			boolean found = false;
			for (WorldType type : types)
			{
				if (type == specialMode)
				{
					found = true;
					break;
				}
			}
			assertTrue("Missing special mode: " + specialMode, found);
		}
	}
}

package com.rshub;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class SyncGuardTest
{
	private static final String FULL_KEY = "ABCDEFGHJKLMNPQR";

	@Test
	public void testCompleteKeyInRsHubGroupTriggers()
	{
		assertTrue(SyncGuard.isCompleteAppKeyEntry(
			RsHubConfig.CONFIG_GROUP, RsHubConfig.APP_KEY, FULL_KEY));
	}

	@Test
	public void testKeyWithSurroundingWhitespaceIsTrimmed()
	{
		assertTrue(SyncGuard.isCompleteAppKeyEntry(
			RsHubConfig.CONFIG_GROUP, RsHubConfig.APP_KEY, "  " + FULL_KEY + "  "));
	}

	@Test
	public void testShortPartialKeyDoesNotTrigger()
	{
		assertFalse(SyncGuard.isCompleteAppKeyEntry(
			RsHubConfig.CONFIG_GROUP, RsHubConfig.APP_KEY, "ABCDEFG"));
	}

	@Test
	public void testMinLengthKeyTriggers()
	{
		assertTrue(SyncGuard.isCompleteAppKeyEntry(
			RsHubConfig.CONFIG_GROUP, RsHubConfig.APP_KEY, "ABCDEFGH"));
	}

	@Test
	public void testClearedKeyDoesNotTrigger()
	{
		assertFalse(SyncGuard.isCompleteAppKeyEntry(
			RsHubConfig.CONFIG_GROUP, RsHubConfig.APP_KEY, ""));
	}

	@Test
	public void testNullValueDoesNotTrigger()
	{
		assertFalse(SyncGuard.isCompleteAppKeyEntry(
			RsHubConfig.CONFIG_GROUP, RsHubConfig.APP_KEY, null));
	}

	@Test
	public void testOtherConfigItemDoesNotTrigger()
	{
		assertFalse(SyncGuard.isCompleteAppKeyEntry(
			RsHubConfig.CONFIG_GROUP, "syncSlayer", FULL_KEY));
	}

	@Test
	public void testOtherConfigGroupDoesNotTrigger()
	{
		assertFalse(SyncGuard.isCompleteAppKeyEntry(
			"timetracking", RsHubConfig.APP_KEY, FULL_KEY));
	}
}

package com.rshub;

import com.rshub.api.RsHubApiClient;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

/**
 * Reads diary tier completion from known "complete" varbits (Easy/Medium/Hard/Elite).
 * Payload shape: region -&gt; { done, total } where done is completed tiers (0–4).
 */
@Slf4j
@Singleton
public class DiaryMonitor
{
	private static final int LOGIN_SYNC_DELAY_SECONDS = 5;
	private static final int RESYNC_THROTTLE_TICKS = 5;
	private static final int SETTLE_TICKS_AFTER_LOGIN = 20;

	/** Region -> Easy/Medium/Hard/Elite complete varbit ids (WikiSync-style). */
	private static final Map<String, int[]> DIARY_COMPLETE_VARBITS = Map.ofEntries(
		Map.entry("Ardougne", new int[]{4499, 4500, 4501, 4502}),
		Map.entry("Desert", new int[]{4523, 4524, 4525, 4526}),
		Map.entry("Falador", new int[]{4503, 4504, 4505, 4506}),
		Map.entry("Fremennik", new int[]{4531, 4532, 4533, 4534}),
		Map.entry("Kandarin", new int[]{4515, 4516, 4517, 4518}),
		Map.entry("Karamja", new int[]{3577, 3598, 3610, 4567}),
		Map.entry("Kourend & Kebos", new int[]{7929, 7930, 7931, 7932}),
		Map.entry("Lumbridge & Draynor", new int[]{4535, 4536, 4537, 4538}),
		Map.entry("Morytania", new int[]{4527, 4528, 4529, 4530}),
		Map.entry("Varrock", new int[]{4519, 4520, 4521, 4522}),
		Map.entry("Wilderness", new int[]{4507, 4508, 4509, 4510}));

	private final Client client;
	private final ClientThread clientThread;
	private final RsHubConfig config;
	private final RsHubApiClient apiClient;
	private final ScheduledExecutorService executor;

	private GameState previousGameState = GameState.UNKNOWN;
	private boolean diaryCheckPending;
	private boolean settled;
	private int loginTick = -1;
	private int lastReadTick = -1;
	private String lastSyncJson;

	@Inject
	public DiaryMonitor(
		Client client,
		ClientThread clientThread,
		RsHubConfig config,
		RsHubApiClient apiClient,
		ScheduledExecutorService executor)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.executor = executor;
	}

	public void stop()
	{
		previousGameState = GameState.UNKNOWN;
		diaryCheckPending = false;
		settled = false;
		loginTick = -1;
		lastReadTick = -1;
		lastSyncJson = null;
	}

	public void forceSync()
	{
		clientThread.invokeLater(() -> {
			lastSyncJson = null;
			syncDiaries();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState newState = event.getGameState();
		if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN)
		{
			settled = false;
			loginTick = -1;
			executor.schedule(
				() -> clientThread.invokeLater(() -> {
					settled = true;
					syncDiaries();
				}),
				LOGIN_SYNC_DELAY_SECONDS,
				TimeUnit.SECONDS);
		}
		else if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN)
		{
			if (settled)
			{
				syncDiaries();
			}
			settled = false;
		}
		previousGameState = newState;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		diaryCheckPending = true;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (client.getGameState() == GameState.LOGGED_IN && loginTick < 0)
		{
			loginTick = client.getTickCount();
		}
		if (!settled && loginTick >= 0
			&& client.getTickCount() - loginTick >= SETTLE_TICKS_AFTER_LOGIN)
		{
			settled = true;
			syncDiaries();
			return;
		}
		if (!settled || !diaryCheckPending)
		{
			return;
		}
		if (lastReadTick != -1 && client.getTickCount() - lastReadTick < RESYNC_THROTTLE_TICKS)
		{
			return;
		}
		diaryCheckPending = false;
		lastReadTick = client.getTickCount();
		syncDiaries();
	}

	private void syncDiaries()
	{
		if (!config.syncDiaries() || !SyncGuard.hasAppKey(config) || GameModeUtil.isSpecialGameMode(client))
		{
			return;
		}
		String player = SyncGuard.getPlayerUsername(client);
		if (player == null)
		{
			return;
		}

		Map<String, Object> diaries = new LinkedHashMap<>();
		for (Map.Entry<String, int[]> entry : DIARY_COMPLETE_VARBITS.entrySet())
		{
			int done = 0;
			for (int varbit : entry.getValue())
			{
				if (client.getVarbitValue(varbit) == 1)
				{
					done++;
				}
			}
			Map<String, Object> region = new LinkedHashMap<>();
			region.put("done", done);
			region.put("total", 4);
			diaries.put(entry.getKey(), region);
		}

		Map<String, Object> body = new LinkedHashMap<>();
		body.put("player", player);
		body.put("diaries", diaries);
		body.put("ts", System.currentTimeMillis());

		String json = body.toString();
		if (json.equals(lastSyncJson))
		{
			return;
		}
		lastSyncJson = json;
		apiClient.postDiaries(body);
		log.debug("Diaries sync for {}", player);
	}
}

