package com.rshub;

import com.rshub.api.RsHubApiClient;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

@Slf4j
@Singleton
public class CombatAchievementMonitor
{
	private static final int LOGIN_SYNC_DELAY_SECONDS = 3;
	private static final int RESYNC_THROTTLE_TICKS = 3;
	private static final int CA_TOTAL = 2000;

	/** WikiSync-ordered CA completion VarPlayers. */
	private static final int[] COMBAT_ACHIEVEMENT_VARPS = {
		3116, 3117, 3118, 3119, 3120, 3121, 3122, 3123, 3124, 3125,
		3126, 3127, 3128, 3387, 3718, 3773, 3774, 4204, 4496, 4721};
	private static final Set<Integer> COMBAT_ACHIEVEMENT_VARP_SET = new HashSet<>();

	static
	{
		for (int varp : COMBAT_ACHIEVEMENT_VARPS)
		{
			COMBAT_ACHIEVEMENT_VARP_SET.add(varp);
		}
	}

	private final Client client;
	private final ClientThread clientThread;
	private final RsHubConfig config;
	private final RsHubApiClient apiClient;
	private final ScheduledExecutorService executor;

	private GameState previousGameState = GameState.UNKNOWN;
	private boolean caCheckPending;
	private int lastReadTick = -1;
	private String lastSyncJson;

	@Inject
	public CombatAchievementMonitor(
		Client client,
		ClientThread clientThread,
		RsHubConfig config,
		RsHubApiClient apiClient,
		ScheduledExecutorService executor)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.executor = executor;
	}

	public void stop()
	{
		previousGameState = GameState.UNKNOWN;
		caCheckPending = false;
		lastReadTick = -1;
		lastSyncJson = null;
	}

	public void forceSync()
	{
		clientThread.invokeLater(() -> {
			lastSyncJson = null;
			syncCombatAchievements();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState newState = event.getGameState();
		if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN)
		{
			executor.schedule(
				() -> clientThread.invokeLater(this::syncCombatAchievements),
				LOGIN_SYNC_DELAY_SECONDS,
				TimeUnit.SECONDS);
		}
		else if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN)
		{
			syncCombatAchievements();
		}
		previousGameState = newState;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (COMBAT_ACHIEVEMENT_VARP_SET.contains(event.getVarpId()))
		{
			caCheckPending = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!caCheckPending)
		{
			return;
		}
		if (lastReadTick != -1 && client.getTickCount() - lastReadTick < RESYNC_THROTTLE_TICKS)
		{
			return;
		}
		caCheckPending = false;
		lastReadTick = client.getTickCount();
		syncCombatAchievements();
	}

	private void syncCombatAchievements()
	{
		if (!config.syncCombatAchievements() || !SyncGuard.hasAppKey(config)
			|| GameModeUtil.isSpecialGameMode(client))
		{
			return;
		}
		String player = SyncGuard.getPlayerUsername(client);
		if (player == null)
		{
			return;
		}

		List<Integer> completed = new ArrayList<>();
		for (int index = 0; index < COMBAT_ACHIEVEMENT_VARPS.length; index++)
		{
			int value = client.getVarpValue(COMBAT_ACHIEVEMENT_VARPS[index]);
			for (int bit = 0; bit < 32; bit++)
			{
				if ((value & (1 << bit)) != 0)
				{
					completed.add(32 * index + bit);
				}
			}
		}

		// Point totals are not exposed as a single stable public API; use completed count as caPoints.
		Map<String, Object> body = new LinkedHashMap<>();
		body.put("player", player);
		body.put("caPoints", completed.size());
		body.put("caTotal", CA_TOTAL);
		body.put("completedIds", completed);
		body.put("ts", System.currentTimeMillis());

		String json = body.toString();
		if (json.equals(lastSyncJson))
		{
			return;
		}
		lastSyncJson = json;
		apiClient.postCombatAchievements(body);
		log.debug("CA sync: {} completed for {}", completed.size(), player);
	}
}

package com.rshub;

import com.rshub.api.RsHubApiClient;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.eventbus.Subscribe;

@Slf4j
@Singleton
public class PresenceMonitor
{
	private static final long HEARTBEAT_INTERVAL_MINUTES = 5;

	private final Client client;
	private final RsHubConfig config;
	private final RsHubApiClient apiClient;
	private final ScheduledExecutorService executor;

	private GameState previousGameState = GameState.UNKNOWN;
	private ScheduledFuture<?> heartbeat;

	@Inject
	public PresenceMonitor(
		Client client,
		RsHubConfig config,
		RsHubApiClient apiClient,
		ScheduledExecutorService executor)
	{
		this.client = client;
		this.config = config;
		this.apiClient = apiClient;
		this.executor = executor;
	}

	public void start()
	{
		if (heartbeat != null)
		{
			return;
		}
		heartbeat = executor.scheduleAtFixedRate(
			this::heartbeatIfLoggedIn,
			HEARTBEAT_INTERVAL_MINUTES,
			HEARTBEAT_INTERVAL_MINUTES,
			TimeUnit.MINUTES);
	}

	public void stop()
	{
		if (heartbeat != null)
		{
			heartbeat.cancel(false);
			heartbeat = null;
		}
		previousGameState = GameState.UNKNOWN;
	}

	public void forceSync()
	{
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			postPresence(true);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState newState = event.getGameState();
		if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN)
		{
			postPresence(true);
		}
		else if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN)
		{
			postPresence(false);
		}
		previousGameState = newState;
	}

	private void heartbeatIfLoggedIn()
	{
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			postPresence(true);
		}
	}

	private void postPresence(boolean online)
	{
		if (!SyncGuard.hasAppKey(config) || GameModeUtil.isSpecialGameMode(client))
		{
			return;
		}
		String player = SyncGuard.getPlayerUsername(client);
		if (player == null)
		{
			return;
		}

		Map<String, Object> body = new LinkedHashMap<>();
		body.put("player", player);
		body.put("online", online);
		body.put("world", client.getWorld());
		body.put("ts", System.currentTimeMillis());
		apiClient.postPresence(body);
		log.debug("Presence sync online={} world={}", online, client.getWorld());
	}
}

