		Map.entry(7, "Krystilia"),
		Map.entry(8, "Konar quo Maten"),
		Map.entry(9, "Aya"),
		Map.entry(10, "Sumona"),
		Map.entry(11, "Spria"),
		Map.entry(12, "Steve"),
		Map.entry(15, "Turael"),
		Map.entry(16, "Aya"));

	private final Client client;
	private final ClientThread clientThread;
	private final RsHubConfig config;
	private final RsHubApiClient apiClient;
	private final ScheduledExecutorService executor;

	private GameState previousGameState = GameState.UNKNOWN;
	private boolean syncPending;
	private int lastReadTick = -1;
	private String lastSyncJson;

	@Inject
	public SlayerMonitor(
		Client client,
		ClientThread clientThread,
		RsHubConfig config,
		RsHubApiClient apiClient,
		ScheduledExecutorService executor)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.executor = executor;
	}

	public void stop()
	{
		previousGameState = GameState.UNKNOWN;
		syncPending = false;
		lastReadTick = -1;
		lastSyncJson = null;
	}

	public void forceSync()
	{
		clientThread.invokeLater(() -> {
			lastSyncJson = null;
			syncSlayer();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState newState = event.getGameState();
		if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN)
		{
			executor.schedule(
				() -> clientThread.invokeLater(this::syncSlayer),
				LOGIN_SYNC_DELAY_SECONDS,
				TimeUnit.SECONDS);
		}
		else if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN)
		{
			syncSlayer();
		}
		previousGameState = newState;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (WATCHED_VARPS.contains(event.getVarpId()) || WATCHED_VARBITS.contains(event.getVarbitId()))
		{
			syncPending = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!syncPending)
		{
			return;
		}
		if (lastReadTick != -1 && client.getTickCount() - lastReadTick < RESYNC_THROTTLE_TICKS)
		{
			return;
		}
		syncPending = false;
		lastReadTick = client.getTickCount();
		syncSlayer();
	}

	private void syncSlayer()
	{
		if (!config.syncSlayer() || !SyncGuard.hasAppKey(config) || GameModeUtil.isSpecialGameMode(client))
		{
			return;
		}
		String player = SyncGuard.getPlayerUsername(client);
		if (player == null)
		{
			return;
		}

		int taskId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
		int remaining = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		int amount = client.getVarpValue(VarPlayerID.SLAYER_COUNT_ORIGINAL);
		int bossTaskId = client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID);
		int masterId = client.getVarbitValue(VarbitID.SLAYER_MASTER);
		int points = client.getVarbitValue(VarbitID.SLAYER_POINTS);
		int streak = client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED);

		Map<String, Object> body = new LinkedHashMap<>();
		body.put("player", player);
		body.put("points", points);
		body.put("streak", streak);
		body.put("taskCount", streak);

		if (remaining > 0 && taskId != 0)
		{
			String monster = resolveTaskName(taskId, bossTaskId == 0 ? null : bossTaskId);
			if (monster == null || monster.isBlank())
			{
				monster = "Task #" + taskId;
			}
			Map<String, Object> task = new LinkedHashMap<>();
			task.put("monster", monster);
			task.put("amount", amount > 0 ? amount : remaining);
			task.put("remaining", remaining);
			task.put("master", MASTER_NAMES.getOrDefault(masterId, "Unknown"));
			body.put("task", task);
		}

		body.put("blocked", decodeBlockedNames());
		body.put("ts", System.currentTimeMillis());

		String json = body.toString();
		if (json.equals(lastSyncJson))
		{
			return;
		}
		lastSyncJson = json;
		apiClient.postSlayer(body);
		log.debug("Slayer sync for {}", player);
	}

	private List<String> decodeBlockedNames()
	{
		List<String> names = new ArrayList<>();
		for (int varp : BLOCK_LIST_VARPS)
		{
			int raw = client.getVarpValue(varp);
			for (int shift = 0; shift <= 24; shift += 8)
			{
				int id = (raw >> shift) & 0xFF;
				if (id == 0)
				{
					continue;
				}
				String name = resolveTaskName(id, null);
				names.add(name != null ? name : ("Task #" + id));
			}
		}
		return names;
	}

	private String resolveTaskName(int taskId, Integer bossTaskId)
	{
		try
		{
			int taskDbRow;
			if (taskId == BOSS_TASK_SENTINEL && bossTaskId != null)
			{
				List<Integer> bossRows = client.getDBRowsByValue(
					DBTableID.SlayerTaskSublist.ID,
					DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID,
					0,
					bossTaskId);
				if (bossRows.isEmpty())
				{
					return null;
				}
				taskDbRow = (Integer) client.getDBTableField(
					bossRows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0)[0];
			}
			else
			{
				List<Integer> taskRows = client.getDBRowsByValue(
					DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, taskId);
				if (taskRows.isEmpty())
				{
					return null;
				}
				taskDbRow = taskRows.get(0);
			}
			return (String) client.getDBTableField(
				taskDbRow, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0)[0];
		}
		catch (RuntimeException e)
		{
			log.debug("Slayer task name resolution failed for task {}", taskId, e);
			return null;
		}
	}
}

package com.rshub.api;

import com.google.gson.Gson;
import com.rshub.GameModeUtil;
import com.rshub.RsHubConfig;
import com.rshub.SyncGuard;
import java.io.IOException;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

@Slf4j
@Singleton
public class RsHubApiClient
{
	private static final long REQUEST_TIMEOUT_SECONDS = 10;
	private static final long LARGE_REQUEST_TIMEOUT_SECONDS = 60;
	private static final MediaType JSON_MEDIA_TYPE = MediaType.parse("application/json");
	private static final int HTTP_OK_MIN = 200;
	private static final int HTTP_OK_MAX = 300;

	private static final String PRESENCE_ENDPOINT = "/api/runelite/presence";
	private static final String SLAYER_ENDPOINT = "/api/runelite/slayer";
	private static final String LOOT_ENDPOINT = "/api/runelite/loot";
	private static final String QUESTS_ENDPOINT = "/api/runelite/quests";
	private static final String DIARIES_ENDPOINT = "/api/runelite/diaries";
	private static final String COMBAT_ACHIEVEMENTS_ENDPOINT = "/api/runelite/combat-achievements";
	private static final String BANK_ENDPOINT = "/api/runelite/bank";
	private static final String COLLECTION_LOG_ENDPOINT = "/api/runelite/collection-log";
	private static final String TIMERS_ENDPOINT = "/api/runelite/timers";
	private static final String PBS_ENDPOINT = "/api/runelite/pbs";

	private final RsHubConfig config;
	private final Client client;
	private final Gson gson;
	private final OkHttpClient okHttpClient;
	private final OkHttpClient largeRequestClient;
	private final Map<String, String> lastSentBodyByType = new ConcurrentHashMap<>();

	@Inject
	public RsHubApiClient(RsHubConfig config, Client client, Gson gson, OkHttpClient okHttpClient)
	{
		this.config = config;
		this.client = client;
		this.gson = gson;
		this.okHttpClient = okHttpClient.newBuilder()
			.callTimeout(REQUEST_TIMEOUT_SECONDS, TimeUnit.SECONDS)
			.build();
		this.largeRequestClient = okHttpClient.newBuilder()
			.callTimeout(LARGE_REQUEST_TIMEOUT_SECONDS, TimeUnit.SECONDS)
			.readTimeout(LARGE_REQUEST_TIMEOUT_SECONDS, TimeUnit.SECONDS)
			.build();
	}

	public void postPresence(Map<String, Object> body)
	{
		postAsync(PRESENCE_ENDPOINT, gson.toJson(body), "presence", false, true);
	}

	public void postSlayer(Map<String, Object> body)
	{
		postAsync(SLAYER_ENDPOINT, gson.toJson(body), "slayer", false, true);
	}

	public void postLoot(Map<String, Object> body)
	{
		// Append-style batches: never dedupe.
		postAsync(LOOT_ENDPOINT, gson.toJson(body), "loot", true, false);
	}

	public void postQuests(Map<String, Object> body)
	{
		postAsync(QUESTS_ENDPOINT, gson.toJson(body), "quests", false, true);
	}

	public void postDiaries(Map<String, Object> body)
	{
		postAsync(DIARIES_ENDPOINT, gson.toJson(body), "diaries", false, true);
	}

	public void postCombatAchievements(Map<String, Object> body)
	{
		postAsync(COMBAT_ACHIEVEMENTS_ENDPOINT, gson.toJson(body), "combat-achievements", false, true);
	}

	public void postBank(Map<String, Object> body)
	{
		postAsync(BANK_ENDPOINT, gson.toJson(body), "bank", true, true);
	}

	public void postCollectionLog(Map<String, Object> body)
	{
		postAsync(COLLECTION_LOG_ENDPOINT, gson.toJson(body), "collection-log", true, true);
	}

	public void postTimers(Map<String, Object> body)
	{
		postAsync(TIMERS_ENDPOINT, gson.toJson(body), "timers", false, true);
	}

	public void postPbs(Map<String, Object> body)
	{
		postAsync(PBS_ENDPOINT, gson.toJson(body), "pbs", false, true);
	}

	public void clearDedupe()
	{
		lastSentBodyByType.clear();
	}

	@SuppressWarnings("unchecked")
	private String dedupeKey(String json)
	{
		try
		{
			Map<String, Object> map = gson.fromJson(json, Map.class);
			if (map == null)
			{
				return json;
			}
			map.remove("ts");
			return gson.toJson(map);
		}
		catch (RuntimeException e)
		{
			return json;
		}
	}

	private void postAsync(String endpoint, String json, String syncType, boolean largeRequest, boolean dedupe)
	{
		if (!SyncGuard.hasAppKey(config))
		{
			log.debug("Skipping {} sync: no App Key configured", syncType);
			return;
		}
		if (GameModeUtil.isSpecialGameMode(client))
		{
			log.debug("Skipping {} sync: special game mode", syncType);
			return;
		}

		if (dedupe)
		{
			String key = dedupeKey(json);
			String previous = lastSentBodyByType.get(syncType);
			if (previous != null && previous.equals(key))
			{
				log.debug("Skipping {} sync: identical to last sent request", syncType);
				return;
			}
		}

		String base = config.apiBaseUrl();
		if (base == null || base.isBlank())
		{
			base = "https://api.rshub.app";
		}
		base = base.trim();
		if (base.endsWith("/"))
		{
			base = base.substring(0, base.length() - 1);
		}

		String url = base + endpoint;
		Request request = new Request.Builder()
			.url(url)
			.header("Content-Type", "application/json")
			.header("X-RuneLite-Key", config.appKey().trim())
			.post(RequestBody.create(JSON_MEDIA_TYPE, json))
			.build();

		OkHttpClient http = largeRequest ? largeRequestClient : okHttpClient;
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("Failed to send {} sync to RSHub API: {}", syncType, e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try
				{
					int code = response.code();
					if (code >= HTTP_OK_MIN && code < HTTP_OK_MAX)
					{
						if (dedupe)
						{
							lastSentBodyByType.put(syncType, dedupeKey(json));
						}
						log.debug("RSHub {} sync ok", syncType);
					}
					else
					{
						log.warn("RSHub API returned {} for {} sync", code, syncType);
					}
				}
				finally
				{
					response.close();
				}
			}
		});
	}
}

package com.rshub;

import com.rshub.api.RsHubApiClient;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.NPC;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;

@Slf4j
@Singleton
public class LootMonitor
{
	private static final int FLUSH_INTERVAL_SECONDS = 120;

	private final Client client;
	private final RsHubConfig config;
	private final RsHubApiClient apiClient;
	private final ItemManager itemManager;
	private final ScheduledExecutorService executor;

	private final List<Map<String, Object>> pendingDrops = new ArrayList<>();
	private final Map<String, Integer> recentNpcIds = new LinkedHashMap<>();
	private GameState previousGameState = GameState.UNKNOWN;
	private ScheduledFuture<?> flushTask;

	@Inject
	public LootMonitor(
		Client client,
		RsHubConfig config,
		RsHubApiClient apiClient,
		ItemManager itemManager,
		ScheduledExecutorService executor)
	{
		this.client = client;
		this.config = config;
		this.apiClient = apiClient;
		this.itemManager = itemManager;
		this.executor = executor;
	}

	public void start()
	{
		if (flushTask != null)
		{
			return;
		}
		flushTask = executor.scheduleAtFixedRate(
			this::flushDrops,
			FLUSH_INTERVAL_SECONDS,
			FLUSH_INTERVAL_SECONDS,
			TimeUnit.SECONDS);
	}

	public void stop()
	{
		if (flushTask != null)
		{
			flushTask.cancel(false);
			flushTask = null;
		}
		flushDrops();
		previousGameState = GameState.UNKNOWN;
		recentNpcIds.clear();
	}

	public void forceSync()
	{
		flushDrops();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState newState = event.getGameState();
		if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN)
		{
			flushDrops();
		}
		previousGameState = newState;
	}

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		NPC npc = event.getNpc();
		if (npc != null && npc.getName() != null)
		{
			recentNpcIds.put(npc.getName(), npc.getId());
		}
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		if (event.getType() != LootRecordType.NPC && event.getType() != LootRecordType.EVENT)
		{
			return;
		}
		if (!config.syncLoot() || !SyncGuard.hasAppKey(config) || GameModeUtil.isSpecialGameMode(client))
		{
			return;
		}

		String source = event.getName() != null ? event.getName() : "Unknown";
		long ts = System.currentTimeMillis();
		for (ItemStack stack : event.getItems())
		{
			int itemId = stack.getId();
			int qty = stack.getQuantity();
			if (itemId < 0 || qty <= 0)
			{
				continue;
			}
			ItemComposition comp = itemManager.getItemComposition(itemId);
			String itemName = comp != null ? comp.getName() : ("Item " + itemId);
			int value = itemManager.getItemPrice(itemId) * qty;

			Map<String, Object> drop = new LinkedHashMap<>();
			drop.put("id", UUID.randomUUID().toString());
			drop.put("ts", ts);
			drop.put("itemName", itemName);
			drop.put("itemId", itemId);
			drop.put("qty", qty);
			drop.put("value", value);
			drop.put("source", source);
			drop.put("rarity", 0);
			synchronized (pendingDrops)
			{
				pendingDrops.add(drop);
			}
		}
	}

	private void flushDrops()
	{
		List<Map<String, Object>> batch;
		synchronized (pendingDrops)
		{
			if (pendingDrops.isEmpty())
			{
				return;
			}
			batch = new ArrayList<>(pendingDrops);
			pendingDrops.clear();
		}

		if (!config.syncLoot() || !SyncGuard.hasAppKey(config) || GameModeUtil.isSpecialGameMode(client))
		{
			return;
		}
		String player = SyncGuard.getPlayerUsername(client);
		if (player == null)
		{
			synchronized (pendingDrops)
			{
				pendingDrops.addAll(0, batch);
			}
			return;
		}

		Map<String, Object> body = new LinkedHashMap<>();
		body.put("player", player);
		body.put("drops", batch);
		apiClient.postLoot(body);
		log.debug("Loot flush: {} drops for {}", batch.size(), player);
	}
}

package com.rshub;

import com.google.inject.Provides;
import com.rshub.api.RsHubApiClient;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "RSHub",
	description = "Sync slayer, loot, bank, timers, quests, diaries and collection log to the RSHub app.")
public class RsHubPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private RsHubConfig config;

	@Inject
	private EventBus eventBus;

	@Inject
	private RsHubApiClient apiClient;

	@Inject
	private PresenceMonitor presenceMonitor;

	@Inject
	private SlayerMonitor slayerMonitor;

	@Inject
	private LootMonitor lootMonitor;

	@Inject
	private QuestMonitor questMonitor;

	@Inject
	private DiaryMonitor diaryMonitor;

	@Inject
	private CombatAchievementMonitor combatAchievementMonitor;

	@Inject
	private BankMonitor bankMonitor;

	@Inject
	private CollectionLogMonitor collectionLogMonitor;

	@Inject
	private TimerMonitor timerMonitor;

	@Override
	protected void startUp()
	{
		log.debug("RSHub started");
		eventBus.register(this);
		eventBus.register(presenceMonitor);
		eventBus.register(slayerMonitor);
		eventBus.register(lootMonitor);
		eventBus.register(questMonitor);
		eventBus.register(diaryMonitor);
		eventBus.register(combatAchievementMonitor);
		eventBus.register(bankMonitor);
		eventBus.register(collectionLogMonitor);
		eventBus.register(timerMonitor);

		presenceMonitor.start();
		lootMonitor.start();
		timerMonitor.start();
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			forceSyncAll();
		}
	}

	@Override
	protected void shutDown()
	{
		eventBus.unregister(this);
		eventBus.unregister(presenceMonitor);
		eventBus.unregister(slayerMonitor);
		eventBus.unregister(lootMonitor);
		eventBus.unregister(questMonitor);
		eventBus.unregister(diaryMonitor);
		eventBus.unregister(combatAchievementMonitor);
		eventBus.unregister(bankMonitor);
		eventBus.unregister(collectionLogMonitor);
		eventBus.unregister(timerMonitor);

		presenceMonitor.stop();
		slayerMonitor.stop();
		lootMonitor.stop();
		questMonitor.stop();
		diaryMonitor.stop();
		combatAchievementMonitor.stop();
		bankMonitor.stop();
		collectionLogMonitor.stop();
		timerMonitor.stop();
		log.debug("RSHub stopped");
	}

	private void forceSyncAll()
	{
		apiClient.clearDedupe();
		presenceMonitor.forceSync();
		slayerMonitor.forceSync();
		lootMonitor.forceSync();
		questMonitor.forceSync();
		diaryMonitor.forceSync();
		combatAchievementMonitor.forceSync();
		bankMonitor.forceSync();
		collectionLogMonitor.forceSync();
		timerMonitor.forceSync();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!SyncGuard.isCompleteAppKeyEntry(event.getGroup(), event.getKey(), event.getNewValue()))
		{
			return;
		}
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		log.debug("RSHub App Key entered while logged in; running full sync");
		forceSyncAll();
	}

	@Provides
	RsHubConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RsHubConfig.class);
	}
}

