	private final ClientThread clientThread;
	private final RsHubConfig config;
	private final RsHubApiClient apiClient;
	private final ItemManager itemManager;
	private final ScheduledExecutorService executor;
	private final ConfigManager configManager;
	private final Gson gson;

	private String lastSyncJson;
	private Map<String, Object> pendingBody;
	private Map<String, Object> lastPostedBody;
	private ScheduledFuture<?> pendingSync;

	@Inject
	public BankMonitor(
		Client client,
		ClientThread clientThread,
		RsHubConfig config,
		RsHubApiClient apiClient,
		ItemManager itemManager,
		ScheduledExecutorService executor,
		ConfigManager configManager,
		Gson gson)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.itemManager = itemManager;
		this.executor = executor;
		this.configManager = configManager;
		this.gson = gson;
		this.lastPostedBody = loadLastBank();
	}

	public void stop()
	{
		if (pendingSync != null)
		{
			pendingSync.cancel(false);
		}
		flushPending();
		lastSyncJson = null;
		pendingBody = null;
	}

	public void forceSync()
	{
		clientThread.invokeLater(() -> {
			lastSyncJson = null;
			Map<String, Object> body = buildPayload();
			if (body == null)
			{
				if (lastPostedBody == null)
				{
					lastPostedBody = loadLastBank();
				}
				body = lastPostedBody;
			}
			if (body == null)
			{
				return;
			}
			pendingBody = body;
			flushPending();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		forceSync();
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.BANK)
		{
			return;
		}
		if (!config.syncBank() || !SyncGuard.hasAppKey(config) || GameModeUtil.isSpecialGameMode(client))
		{
			return;
		}

		Map<String, Object> body = buildPayload();
		if (body == null)
		{
			return;
		}
		String json = body.toString();
		if (json.equals(lastSyncJson))
		{
			return;
		}

		pendingBody = body;
		if (pendingSync != null)
		{
			pendingSync.cancel(false);
		}
		if (lastSyncJson == null)
		{
			flushPending();
		}
		else
		{
			pendingSync = executor.schedule(this::flushPending, DEBOUNCE_SECONDS, TimeUnit.SECONDS);
		}
	}

	private Map<String, Object> buildPayload()
	{
		String player = SyncGuard.getPlayerUsername(client);
		if (player == null)
		{
			return null;
		}
		ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		if (bank == null)
		{
			return null;
		}

		List<Map<String, Object>> items = new ArrayList<>();
		long coins = 0;
		for (Item item : bank.getItems())
		{
			int id = item.getId();
			int qty = item.getQuantity();
			if (id < 0 || qty <= 0)
			{
				continue;
			}
			ItemComposition comp = itemManager.getItemComposition(id);
			if (comp != null && comp.getPlaceholderTemplateId() != -1)
			{
				continue;
			}
			int canonical = itemManager.canonicalize(id);
			if (canonical == COINS_ID)
			{
				coins += qty;
			}
			String name = comp != null ? comp.getName() : ("Item " + canonical);
			Map<String, Object> row = new LinkedHashMap<>();
			row.put("id", canonical);
			row.put("name", name);
			row.put("qty", qty);
			row.put("tab", 0);
			items.add(row);
		}

		Map<String, Object> body = new LinkedHashMap<>();
		body.put("player", player);
		body.put("coins", coins);
		body.put("items", items);
		body.put("ts", System.currentTimeMillis());
		return body;
	}

	private synchronized void flushPending()
	{
		if (pendingBody == null)
		{
			return;
		}
		lastSyncJson = pendingBody.toString();
		lastPostedBody = pendingBody;
		persistLastBank(pendingBody);
		apiClient.postBank(pendingBody);
		log.debug("Bank sync for {}", pendingBody.get("player"));
		pendingBody = null;
		pendingSync = null;
	}

	private void persistLastBank(Map<String, Object> body)
	{
		try
		{
			configManager.setConfiguration(RsHubConfig.CONFIG_GROUP, LAST_BANK_KEY, gson.toJson(body));
		}
		catch (RuntimeException e)
		{
			log.debug("Could not persist last bank snapshot", e);
		}
	}

	private Map<String, Object> loadLastBank()
	{
		try
		{
			String raw = configManager.getConfiguration(RsHubConfig.CONFIG_GROUP, LAST_BANK_KEY);
			if (raw == null || raw.isBlank())
			{
				return null;
			}
			return gson.fromJson(raw, BANK_BODY_TYPE);
		}
		catch (RuntimeException e)
		{
			log.debug("Could not load last bank snapshot", e);
			return null;
		}
	}
}

package com.rshub;

import net.runelite.api.Client;
import net.runelite.api.Player;

/**
 * Shared pre-sync validation checks used by all monitors.
 */
public final class SyncGuard
{
	/**
	 * Minimum length treated as a complete app key. Rejects partial typing / clears.
	 */
	public static final int APP_KEY_MIN_LENGTH = 8;

	private SyncGuard()
	{
	}

	public static boolean hasAppKey(RsHubConfig config)
	{
		String key = config.appKey();
		return key != null && !key.isBlank();
	}

	/**
	 * Returns true when a ConfigChanged event represents a complete App Key entry.
	 */
	public static boolean isCompleteAppKeyEntry(String group, String key, String newValue)
	{
		if (!RsHubConfig.CONFIG_GROUP.equals(group) || !RsHubConfig.APP_KEY.equals(key))
		{
			return false;
		}
		return newValue != null && newValue.trim().length() >= APP_KEY_MIN_LENGTH;
	}

	/**
	 * Returns the local player's username, or null if unavailable.
	 */
	public static String getPlayerUsername(Client client)
	{
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			return null;
		}
		String name = localPlayer.getName();
		if (name == null || name.isBlank())
		{
			return null;
		}
		return name;
	}
}

package com.rshub;

import com.rshub.api.RsHubApiClient;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;

/**
 * Hub-safe collection log sync: only captures items when the player opens the log.
 * Listens for draw script 4100 — does not inject menuAction or runScript.
 */
@Slf4j
@Singleton
public class CollectionLogMonitor
{
	private static final int DRAW_SCRIPT = 4100;
	private static final int SYNC_DELAY_TICKS = 2;
	/** Approximate known collection log total for UI; server may refine. */
	private static final int CLOG_TOTAL_ESTIMATE = 1443;

	private final Client client;
	private final ClientThread clientThread;
	private final RsHubConfig config;
	private final RsHubApiClient apiClient;
	private final ItemManager itemManager;

	private final Map<Integer, Integer> obtainedQuantityByItemId = new HashMap<>();
	private GameState previousGameState = GameState.UNKNOWN;
	private boolean captureActive;
	private int tickScriptFired = -1;
	private String lastSyncJson;

	@Inject
	public CollectionLogMonitor(
		Client client,
		ClientThread clientThread,
		RsHubConfig config,
		RsHubApiClient apiClient,
		ItemManager itemManager)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.itemManager = itemManager;
	}

	public void stop()
	{
		resetSessionState();
		previousGameState = GameState.UNKNOWN;
		lastSyncJson = null;
	}

	public void forceSync()
	{
		clientThread.invokeLater(() -> {
			lastSyncJson = null;
			syncCollectionLog();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN)
		{
			resetSessionState();
		}
		else if (previousGameState == GameState.LOGGED_IN && state != GameState.LOGGED_IN)
		{
			syncCollectionLog();
			resetSessionState();
		}
		previousGameState = state;
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		// Collection log interface group is commonly 621; enable capture when any clog UI loads.
		if (event.getGroupId() == 621)
		{
			captureActive = true;
		}
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() != DRAW_SCRIPT || !captureActive)
		{
			return;
		}
		if (!config.syncCollectionLog() || !SyncGuard.hasAppKey(config))
		{
			return;
		}
		Object[] args = event.getScriptEvent().getArguments();
		if (args == null || args.length < 2 || !(args[1] instanceof Integer))
		{
			return;
		}
		int itemId = (Integer) args[1];
		int quantity = args.length > 2 && args[2] instanceof Integer ? (Integer) args[2] : 1;
		obtainedQuantityByItemId.put(itemId, quantity);
		tickScriptFired = client.getTickCount();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (tickScriptFired == -1 || tickScriptFired + SYNC_DELAY_TICKS > client.getTickCount())
		{
			return;
		}
		tickScriptFired = -1;
		syncCollectionLog();
	}

	private void syncCollectionLog()
	{
		if (!config.syncCollectionLog() || !SyncGuard.hasAppKey(config)
			|| GameModeUtil.isSpecialGameMode(client))
		{
			return;
		}
		String player = SyncGuard.getPlayerUsername(client);
		if (player == null || obtainedQuantityByItemId.isEmpty())
		{
			return;
		}

		Map<Integer, Integer> sorted = new TreeMap<>(obtainedQuantityByItemId);
		List<Map<String, Object>> items = new ArrayList<>();
		for (Map.Entry<Integer, Integer> e : sorted.entrySet())
		{
			ItemComposition comp = itemManager.getItemComposition(e.getKey());
			Map<String, Object> row = new LinkedHashMap<>();
			row.put("id", e.getKey());
			row.put("name", comp != null ? comp.getName() : ("Item " + e.getKey()));
			row.put("qty", e.getValue());
			items.add(row);
		}

		Map<String, Object> body = new LinkedHashMap<>();
		body.put("player", player);
		body.put("obtained", items.size());
		body.put("total", CLOG_TOTAL_ESTIMATE);
		body.put("items", items);
		body.put("ts", System.currentTimeMillis());

		String json = body.toString();
		if (json.equals(lastSyncJson))
		{
			return;
		}
		lastSyncJson = json;
		apiClient.postCollectionLog(body);
		log.debug("Collection log sync: {} items for {}", items.size(), player);
	}

	private void resetSessionState()
	{
		obtainedQuantityByItemId.clear();
		captureActive = false;
		tickScriptFired = -1;
	}
}

package com.rshub;

import com.rshub.api.RsHubApiClient;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

@Slf4j
@Singleton
public class QuestMonitor
{
	private static final int LOGIN_SYNC_DELAY_SECONDS = 3;
	private static final int RESYNC_THROTTLE_TICKS = 3;

	private final Client client;
	private final ClientThread clientThread;
	private final RsHubConfig config;
	private final RsHubApiClient apiClient;
	private final ScheduledExecutorService executor;

	private GameState previousGameState = GameState.UNKNOWN;
	private boolean questCheckPending;
	private int lastReadTick = -1;
	private String lastSyncJson;

	@Inject
	public QuestMonitor(
		Client client,
		ClientThread clientThread,
		RsHubConfig config,
		RsHubApiClient apiClient,
		ScheduledExecutorService executor)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.apiClient = apiClient;
		this.executor = executor;
	}

	public void stop()
	{
		previousGameState = GameState.UNKNOWN;
		questCheckPending = false;
		lastReadTick = -1;
		lastSyncJson = null;
	}

	public void forceSync()
	{
		clientThread.invokeLater(() -> {
			lastSyncJson = null;
			syncQuests();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState newState = event.getGameState();
		if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN)
		{
			executor.schedule(
				() -> clientThread.invokeLater(this::syncQuests),
				LOGIN_SYNC_DELAY_SECONDS,
				TimeUnit.SECONDS);
		}
		else if (previousGameState == GameState.LOGGED_IN && newState != GameState.LOGGED_IN)
		{
			syncQuests();
		}
		previousGameState = newState;
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		questCheckPending = true;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!questCheckPending)
		{
			return;
		}
		if (lastReadTick != -1 && client.getTickCount() - lastReadTick < RESYNC_THROTTLE_TICKS)
		{
			return;
		}
		questCheckPending = false;
		lastReadTick = client.getTickCount();
		syncQuests();
	}

	private void syncQuests()
	{
		if (!config.syncQuests() || !SyncGuard.hasAppKey(config) || GameModeUtil.isSpecialGameMode(client))
		{
			return;
		}
		String player = SyncGuard.getPlayerUsername(client);
		if (player == null)
		{
			return;
		}

		Map<String, Integer> quests = new TreeMap<>();
		int complete = 0;
		int total = 0;
		for (Quest quest : Quest.values())
		{
			int status = toStatus(quest.getState(client));
			quests.put(quest.getName(), status);
			total++;
			if (status == 2)
			{
				complete++;
			}
		}

		Map<String, Object> body = new LinkedHashMap<>();
		body.put("player", player);
		body.put("questPoints", complete);
		body.put("questsComplete", complete);
		body.put("questsTotal", total);
		body.put("quests", quests);
		body.put("ts", System.currentTimeMillis());

		String json = body.toString();
		if (json.equals(lastSyncJson))
		{
			return;
		}
		lastSyncJson = json;
		apiClient.postQuests(body);
		log.debug("Quests sync: {}/{} for {}", complete, total, player);
	}

	private static int toStatus(QuestState state)
	{
		if (state == QuestState.FINISHED)
		{
			return 2;
		}
		if (state == QuestState.IN_PROGRESS)
		{
			return 1;
		}
		return 0;
	}
}

package com.rshub;

import java.util.EnumSet;
import net.runelite.api.Client;
import net.runelite.api.WorldType;

/**
 * Detects special game modes that must not sync (avoids polluting main-game data).
 */
public final class GameModeUtil
{
	private static final EnumSet<WorldType> SPECIAL_GAME_MODES = EnumSet.of(
		WorldType.SEASONAL,
		WorldType.DEADMAN,
		WorldType.FRESH_START_WORLD,
		WorldType.TOURNAMENT_WORLD,
		WorldType.BETA_WORLD,
		WorldType.NOSAVE_MODE,
		WorldType.QUEST_SPEEDRUNNING);

	private GameModeUtil()
	{
	}

	public static boolean isSpecialGameMode(Client client)
	{
		EnumSet<WorldType> worldTypes = client.getWorldType();
		for (WorldType special : SPECIAL_GAME_MODES)
		{
			if (worldTypes.contains(special))
			{
				return true;
			}
		}
		return false;
	}
}

package com.rshub;

import com.rshub.api.RsHubApiClient;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.timetracking.TimeTrackingConfig;

/**
 * Reads birdhouse (and any available farming) timers from RuneLite Time Tracking
 * RSProfile config. Enable the Time Tracking plugin and visit patches/houses in-game.
 */
@Slf4j
@Singleton
public class TimerMonitor
{
	private static final int SYNC_INTERVAL_SECONDS = 60;
	private static final int LOGIN_SYNC_DELAY_SECONDS = 5;
	private static final long BIRD_HOUSE_DURATION_SECONDS = Duration.ofMinutes(50).getSeconds();

	private static final Object[][] BIRD_HOUSE_SPACES = {
		{"Mushroom Meadow (North)", VarPlayerID.BIRDHOUSE_TRANSMIT_A},
		{"Mushroom Meadow (South)", VarPlayerID.BIRDHOUSE_TRANSMIT_B},
		{"Verdant Valley (Northeast)", VarPlayerID.BIRDHOUSE_TRANSMIT_C},
		{"Verdant Valley (Southwest)", VarPlayerID.BIRDHOUSE_TRANSMIT_D},
	};

	private final Client client;
	private final RsHubConfig config;
	private final RsHubApiClient apiClient;
	private final ConfigManager configManager;
	private final ScheduledExecutorService executor;

	private ScheduledFuture<?> scheduled;
	private GameState previousGameState = GameState.UNKNOWN;
	private String lastSyncJson;

	@Inject
	public TimerMonitor(
		Client client,
		RsHubConfig config,
		RsHubApiClient apiClient,
		ConfigManager configManager,
		ScheduledExecutorService executor)
	{
		this.client = client;
		this.config = config;
		this.apiClient = apiClient;
		this.configManager = configManager;
		this.executor = executor;
	}

	public void start()
	{
		if (scheduled != null)
		{
			return;
		}
		scheduled = executor.scheduleAtFixedRate(
			this::sync,
			SYNC_INTERVAL_SECONDS,
			SYNC_INTERVAL_SECONDS,
			TimeUnit.SECONDS);
	}

	public void stop()
	{
		if (scheduled != null)
		{
			scheduled.cancel(false);
			scheduled = null;
		}
		previousGameState = GameState.UNKNOWN;
		lastSyncJson = null;
	}

	public void forceSync()
	{
		executor.execute(() -> {
			lastSyncJson = null;
			sync();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState newState = event.getGameState();
		if (newState == GameState.LOGGED_IN && previousGameState != GameState.LOGGED_IN)
		{
			lastSyncJson = null;
			executor.schedule(this::sync, LOGIN_SYNC_DELAY_SECONDS, TimeUnit.SECONDS);
		}
		previousGameState = newState;
	}

	private void sync()
	{
		if (!config.syncTimers() || !SyncGuard.hasAppKey(config))
		{
			return;
		}
		if (client.getGameState() != GameState.LOGGED_IN || GameModeUtil.isSpecialGameMode(client))
		{
			return;
		}
		String player = SyncGuard.getPlayerUsername(client);
		if (player == null)
		{
			return;
		}

		List<Map<String, Object>> timers = new ArrayList<>();
		collectBirdHouseTimers(timers);
		collectFarmingConfigTimers(timers);

		Map<String, Object> body = new LinkedHashMap<>();
		body.put("player", player);
		body.put("timers", timers);
		body.put("ts", System.currentTimeMillis());

		// Dedup via API client body hash; always post when forceSync cleared lastSyncJson.
		String fingerprint = player + "|" + timers.size() + "|" + timers;
		if (fingerprint.equals(lastSyncJson))
		{
			return;
		}
		lastSyncJson = fingerprint;
		apiClient.postTimers(body);
		log.debug("Timers sync: {} for {}", timers.size(), player);
	}

	private void collectBirdHouseTimers(List<Map<String, Object>> timers)
	{
		long now = Instant.now().getEpochSecond();
		for (Object[] space : BIRD_HOUSE_SPACES)
		{
			String spaceName = (String) space[0];
			int varp = (Integer) space[1];
			String key = TimeTrackingConfig.BIRD_HOUSE + "." + varp;
			String stored = configManager.getRSProfileConfiguration(
				TimeTrackingConfig.CONFIG_GROUP, key);
			if (stored == null)
			{
				continue;
			}
			String[] parts = stored.split(":");
			if (parts.length != 2)
			{
				continue;
			}
			int value;
			long timestamp;
			try
			{
				value = Integer.parseInt(parts[0]);
				timestamp = Long.parseLong(parts[1]);
			}
			catch (NumberFormatException e)
			{
				continue;
			}
			// Seeded when varp is a positive multiple of 3 (RuneLite BirdHouseState).
			if (value <= 0 || value % 3 != 0)
			{
				continue;
			}
			long ready = timestamp + BIRD_HOUSE_DURATION_SECONDS;
			if (ready <= now)
			{
				continue;
			}
			Map<String, Object> timer = new LinkedHashMap<>();
			timer.put("id", "birdhouse-" + varp);
			timer.put("kind", "birdhouse");
			timer.put("label", "Bird House");
			timer.put("detail", spaceName);
			timer.put("readyAt", ready * 1000L);
			timers.add(timer);
		}
	}

	/**
	 * Best-effort scan of timetracking RSProfile keys that look like farming patch data
	 * (region.varbit style values). Without the full FarmingTracker tree this is incomplete;
